public sealed class AgroInfraestruturaRuralRepository:IAgroInfraestruturaRuralRepository{private readonly DapperContext _c; public AgroInfraestruturaRuralRepository(DapperContext c)=>_c=c; public async Task<PagedResult<AgroEstradaVicinalResponse>> ListarEstradasAsync(long t,long e,AgroEstradaVicinalFiltro f,CancellationToken ct){const string cs="select count(*) from sigov.agro_estrada_vicinal where tenant_id=@t and entidade_id=@e and is_deleted=false and (@s is null or situacao=@s) and (@b is null or nome ilike '%'||@b||'%' or codigo ilike '%'||@b||'%')"; const string sql="select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,extensao_km ExtensaoKm,tipo_revestimento TipoRevestimento,situacao,latitude_inicio LatitudeInicio,longitude_inicio LongitudeInicio,latitude_fim LatitudeFim,longitude_fim LongitudeFim,geojson::text GeoJson,observacao,ativo from sigov.agro_estrada_vicinal where tenant_id=@t and entidade_id=@e and is_deleted=false and (@s is null or situacao=@s) and (@b is null or nome ilike '%'||@b||'%' or codigo ilike '%'||@b||'%') order by created_at desc,id desc limit @l offset @o"; using var cn=_c.CreateConnection(); var a=new{t,e,s=f.Status,b=f.Busca,l=f.PageSize,o=(f.Page-1)*f.PageSize}; var total=await cn.ExecuteScalarAsync<long>(new CommandDefinition(cs,a,cancellationToken:ct)); var rows=await cn.QueryAsync<AgroEstradaVicinalResponse>(new CommandDefinition(sql,a,cancellationToken:ct)); return new(rows.AsList(),f.Page,f.PageSize,total);} public async Task<AgroEstradaVicinalResponse?> ObterEstradaAsync(long t,long e,long id,CancellationToken ct){const string sql="select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,extensao_km ExtensaoKm,tipo_revestimento TipoRevestimento,situacao,latitude_inicio LatitudeInicio,longitude_inicio LongitudeInicio,latitude_fim LatitudeFim,longitude_fim LongitudeFim,geojson::text GeoJson,observacao,ativo from sigov.agro_estrada_vicinal where tenant_id=@t and entidade_id=@e and id=@id and is_deleted=false"; using var cn=_c.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<AgroEstradaVicinalResponse>(new CommandDefinition(sql,new{t,e,id},cancellationToken:ct));} public async Task<long> CriarEstradaAsync(long t,long e,long? u,AgroEstradaVicinalCreateRequest r,CancellationToken ct){const string sql="insert into sigov.agro_estrada_vicinal(tenant_id,entidade_id,codigo,nome,localidade_inicio,localidade_fim,comunidades_atendidas,extensao_km,tipo_revestimento,situacao,latitude_inicio,longitude_inicio,latitude_fim,longitude_fim,geojson,observacao,created_by) values(@t,@e,@Codigo,@Nome,@LocalidadeInicio,@LocalidadeFim,coalesce(@ComunidadesAtendidasJson::jsonb,'[]'::jsonb),@ExtensaoKm,@TipoRevestimento,@Situacao,@LatitudeInicio,@LongitudeInicio,@LatitudeFim,@LongitudeFim,@GeoJson::jsonb,@Observacao,@u) returning id"; using var cn=_c.CreateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{t,e,u,r.Codigo,r.Nome,r.LocalidadeInicio,r.LocalidadeFim,r.ComunidadesAtendidasJson,r.ExtensaoKm,r.TipoRevestimento,r.Situacao,r.LatitudeInicio,r.LongitudeInicio,r.LatitudeFim,r.LongitudeFim,r.GeoJson,r.Observacao},cancellationToken:ct));} public async Task AtualizarEstradaAsync(long t,long e,long id,long? u,AgroEstradaVicinalUpdateRequest r,CancellationToken ct){const string sql="update sigov.agro_estrada_vicinal set codigo=@Codigo,nome=@Nome,localidade_inicio=@LocalidadeInicio,localidade_fim=@LocalidadeFim,comunidades_atendidas=coalesce(@ComunidadesAtendidasJson::jsonb,'[]'::jsonb),extensao_km=@ExtensaoKm,tipo_revestimento=@TipoRevestimento,situacao=@Situacao,latitude_inicio=@LatitudeInicio,longitude_inicio=@LongitudeInicio,latitude_fim=@LatitudeFim,longitude_fim=@LongitudeFim,geojson=@GeoJson::jsonb,observacao=@Observacao,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and id=@id and is_deleted=false"; using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition(sql,new{t,e,id,u,r.Codigo,r.Nome,r.LocalidadeInicio,r.LocalidadeFim,r.ComunidadesAtendidasJson,r.ExtensaoKm,r.TipoRevestimento,r.Situacao,r.LatitudeInicio,r.LongitudeInicio,r.LatitudeFim,r.LongitudeFim,r.GeoJson,r.Observacao},cancellationToken:ct));} public async Task ExcluirEstradaAsync(long t,long e,long id,long? u,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_estrada_vicinal set is_deleted=true,ativo=false,deleted_at=now(),deleted_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,u},cancellationToken:ct));}
