eateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{t,e,ex,u,r.ProdutorId,r.PropriedadeId,r.EstradaVicinalId,r.PontoCriticoId,r.Numero,r.TipoOcorrencia,r.Descricao,r.DataOcorrencia,r.Severidade,r.Status,r.Latitude,r.Longitude,r.EvidenciasJson},cancellationToken:ct));} public async Task AtualizarOcorrenciaStatusAsync(long t,long e,long id,string s,long? u,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_ocorrencia_rural set status=@s,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,s,u},cancellationToken:ct));}
