ng var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_manutencao_rural set status=@s,data_execucao=coalesce(@d,data_execucao),updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,s,d,u},cancellationToken:ct));}}
